BEGIN;
CREATE TABLE IF NOT EXISTS mission_bridge_youth_partner_agreements(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,partner_type TEXT NOT NULL CHECK(partner_type IN('child_welfare','school','professional_social_work')),partner_name TEXT NOT NULL,agreement_reference TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',valid_from DATE,valid_until DATE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_transition_youth_profiles(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,age INTEGER NOT NULL CHECK(age BETWEEN 16 AND 25),partner_agreement_id UUID NOT NULL REFERENCES mission_bridge_youth_partner_agreements(id),guardian_or_agency_consent BOOLEAN NOT NULL DEFAULT FALSE,emergency_contact_encrypted TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS mission_bridge_youth_mentor_clearances(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,mentor_user_id TEXT NOT NULL,background_check_reference TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending','cleared','expired','rejected')),checked_at TIMESTAMPTZ,expires_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS mission_bridge_youth_mentor_assignments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,youth_profile_id UUID NOT NULL REFERENCES mission_bridge_transition_youth_profiles(id),mentor_clearance_id UUID NOT NULL REFERENCES mission_bridge_youth_mentor_clearances(id),long_term_commitment_until DATE,private_transport_allowed BOOLEAN NOT NULL DEFAULT FALSE,private_money_allowed BOOLEAN NOT NULL DEFAULT FALSE,status TEXT NOT NULL DEFAULT 'active',CHECK(private_transport_allowed=FALSE),CHECK(private_money_allowed=FALSE));
CREATE TABLE IF NOT EXISTS mission_bridge_youth_meetings(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,assignment_id UUID NOT NULL REFERENCES mission_bridge_youth_mentor_assignments(id),starts_at TIMESTAMPTZ NOT NULL,location_type TEXT NOT NULL CHECK(location_type IN('partner_site','public_space','video')),second_adult_or_recording TEXT NOT NULL,logged BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(logged=TRUE));
CREATE TABLE IF NOT EXISTS mission_bridge_youth_transition_plans(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,youth_profile_id UUID NOT NULL REFERENCES mission_bridge_transition_youth_profiles(id),education JSONB NOT NULL,career JSONB NOT NULL,housing JSONB NOT NULL,employment JSONB NOT NULL,finance JSONB NOT NULL,boundaries JSONB NOT NULL,life_skills JSONB NOT NULL,exit_support_until DATE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_youth_story_consents(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,youth_profile_id UUID NOT NULL REFERENCES mission_bridge_transition_youth_profiles(id),fundraising_use BOOLEAN NOT NULL DEFAULT FALSE,explicit_consent BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(fundraising_use=FALSE));
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['mission_bridge_youth_partner_agreements','mission_bridge_transition_youth_profiles','mission_bridge_youth_mentor_clearances','mission_bridge_youth_mentor_assignments','mission_bridge_youth_meetings','mission_bridge_youth_transition_plans','mission_bridge_youth_story_consents'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK (tenant_id=current_setting(''app.tenant_id'',true))',t);END LOOP;END $$;
COMMIT;
